INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch07$PT156-S4-Q3$batch07$, 156, 4, 3, $batch07$Agree/Disagree$batch07$, $batch07$James: The world is increasingly divided between the computer literate and the computer illiterate. The economic gap between rich and poor is partly responsible for causing this division, but the economic gap will widen because of the increasing importance of computer literacy. Ariel: I disagree. Because of businesses’ increasing need for computer-literate employees, companies will have to train nearly all workers in computer skills. This will lessen the division between the computer literate and the computer illiterate. So whatever might cause the economic gap between rich and poor to widen in the future, it won’t be the importance of computer literacy.$batch07$, $batch07$James and Ariel disagree over whether$batch07$, $batch07$D$batch07$, true, $batch07$Batch 07; question text from local bank.$batch07$ FROM lr_sections s WHERE s.preptest=156 AND s.section=4 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch07$PT156-S4-Q3$batch07$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch07$A$batch07$, $batch07$the economic gap between rich and poor will widen$batch07$, $batch07$Half Scope$batch07$, false FROM lr_questions q WHERE q.qid=$batch07$PT156-S4-Q3$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch07$A$batch07$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch07$B$batch07$, $batch07$the economic gap between rich and poor is now partly responsible for causing the division between the computer literate and the computer illiterate$batch07$, $batch07$Half Scope$batch07$, false FROM lr_questions q WHERE q.qid=$batch07$PT156-S4-Q3$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch07$B$batch07$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch07$C$batch07$, $batch07$businesses’ need for computer-literate employees will increase$batch07$, $batch07$Both Agree$batch07$, false FROM lr_questions q WHERE q.qid=$batch07$PT156-S4-Q3$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch07$C$batch07$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch07$D$batch07$, $batch07$the economic gap between rich and poor will widen as a result of the increasing importance of computer literacy$batch07$, $batch07$Correct$batch07$, true FROM lr_questions q WHERE q.qid=$batch07$PT156-S4-Q3$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch07$D$batch07$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch07$E$batch07$, $batch07$companies will have to train their employees in computer skills$batch07$, $batch07$Half Scope$batch07$, false FROM lr_questions q WHERE q.qid=$batch07$PT156-S4-Q3$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch07$E$batch07$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch07$PT156-S4-Q3$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch07$James's Position$batch07$, $batch07$The economic gap partly causes the divide between the computer literate and illiterate. And the economic gap will widen because computer literacy is becoming more important.$batch07$), (1, $batch07$Ariel's Position$batch07$, $batch07$"I disagree." Companies will have to train nearly everyone, which will shrink the divide. So whatever widens the economic gap, it won't be the importance of computer literacy.$batch07$), (2, $batch07$Evaluate$batch07$, $batch07$Ariel's last sentence aims at James's last clause. Notice what Ariel leaves open: "whatever might cause the economic gap ... to widen". Ariel doesn't deny the gap will widen, only that computer literacy will be the cause.$batch07$), (3, $batch07$Goal$batch07$, $batch07$Whether the importance of computer literacy will cause the economic gap to widen.$batch07$)) v(position,label,body) WHERE q.qid=$batch07$PT156-S4-Q3$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch07$A$batch07$, $batch07$James says the gap will widen. Ariel leaves that open ("whatever might cause" it), so Ariel isn't on the other side.$batch07$), ($batch07$B$batch07$, $batch07$James says this. Ariel never talks about what is causing the divide now.$batch07$), ($batch07$C$batch07$, $batch07$Ariel says businesses' need will increase, and James talks about the "increasing importance of computer literacy". Neither denies it.$batch07$), ($batch07$D$batch07$, $batch07$James: the gap will widen "because of the increasing importance of computer literacy". Ariel: "it won't be the importance of computer literacy".$batch07$), ($batch07$E$batch07$, $batch07$Ariel says companies will have to train workers. James never addresses training.$batch07$)) v(letter,body) WHERE q.qid=$batch07$PT156-S4-Q3$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
